Let $\delta=(\log\log{X})^{-1}$. Clearly we may assume that $\delta$ is sufficiently small in terms of $\eta$, since otherwise the result is trivial. We note that $\ell\ge 2$, since the sum of coordinates of points in $\mathcal{R}$ is 1 but a non-trivial subset of them lies in $[9/25,17/40]$.

Given reals $a_1,\dots,a_{\ell-1}\ge 0$ and $\gamma>0$ and a set $\mathcal{S}\in\mathbb{R}^\ell$, let
\begin{align*}
\mathcal{C}(\mathbf{a};\gamma)&:=\Bigl(a_1,a_1+\gamma\Bigr]\times\dots \times \Bigl(a_{\ell-1},a_{\ell-1}+\gamma\Bigr],\\
\mathcal{C}^+(\mathbf{a};\gamma)&:=\Bigl\{\mathbf{e}\in[\eta/4,1]^\ell:\,(e_1,\dots,e_{\ell-1})\in\mathcal{C}(\mathbf{a};\gamma),\,\sum_{i=1}^\ell e_i\le 1,\,e_\ell\ge 1-\sum_{i=1}^{\ell-1}a_i-\ell\delta \Bigr\},\\
\tilde{\mathbf{1}}_{\mathcal{S}}(n)&:=\begin{cases}
1,\qquad &n=p_1\cdots p_\ell\text{ for some $p_1,\dots,p_{\ell}$ with }\Bigl(\frac{\log{p_1}}{\log{X}},\dots,\frac{\log{p_{\ell}}}{\log{X}}\Bigr)\in\mathcal{S},\\

0,&\text{otherwise.}
\end{cases}
\end{align*}
We see that $\mathbf{1}_{\mathcal{S}}$ and $\tilde{\mathbf{1}}_{\mathcal{S}}$ differ in that the denominators of the fractions are $\log{n}$ and $\log{X}$ respectively.

We cover $[\eta,1]^{\ell-1}$ by $O(\delta^{-(\ell-1)})$ disjoint hypercubes $\mathcal{C}(\mathbf{a},\delta)$ of side length $\delta$ (for example, we can take all $\mathbf{a}\in \{0,\delta,2\delta,\dots,\lceil \delta^{-1}\rceil\delta\}^{\ell-1}$). Let $\overline{\mathcal{R}}\subseteq[\eta,1]^{\ell-1}$ denote the projection of $\mathcal{R}$ onto the first $\ell-1$ coordinates (which is also a closed convex polytope). We see that if $n\in [X^{1-\delta^2},X]$ then $\log{n}$ and $\log{X}$ differ by a factor of at most $1-\delta^2$. In particular, if $\log{p_j}/\log{X}\in [a_j,a_j+\delta]$ then certainly $\log{p_j}/\log{n}\in [a_j,a_j+2\delta]$. This means that if $\mathcal{C}(\mathbf{a};2\delta)\subseteq\overline{\mathcal{R}}$ and $\log{p_j}/\log{X}\in [a_j,a_j+\delta]$ for all $j\le\ell-1$, then $\mathbf{1}_{\mathcal{R}}(p_1\cdots p_\ell)=1$ for all $p_\ell\in[X^{1-\delta^2}/p_1\cdots p_{\ell-1},X/p_1\cdots p_{\ell-1}]$. Thus for $n\in [X^{1-\delta^2},X]$
\begin{equation}
\mathbf{1}_{\mathcal{R}}(n)\tilde{\mathbf{1}}_{\mathcal{C}^+(\mathbf{a};\delta)}(n)=\begin{cases}
0,\qquad &\text{if $\overline{\mathcal{R}}\cap\mathcal{C}(\mathbf{a};2\delta)=\emptyset$},\\
\tilde{\mathbf{1}}_{\mathcal{C}^+(\mathbf{a};\delta)}(n),& \text{if $\mathcal{C}(\mathbf{a};2\delta)\subseteq\overline{\mathcal{R}}$},\\
O(\tilde{\mathbf{1}}_{\mathcal{C}^+(\mathbf{a};\delta)}(n)),&\text{otherwise}.
\end{cases}
\label{eq:RCubeSplit}
\end{equation}
If $\mathcal{C}(\mathbf{a};2\delta)\cap\overline{\mathcal{R}}\ne\emptyset$ but $\mathcal{C}(\mathbf{a};2\delta)\not\subseteq\overline{\mathcal{R}}$ then $\mathcal{C}(\mathbf{a};2\delta)$ intersects the boundary $\partial\overline{\mathcal{R}}$ of $\overline{\mathcal{R}}$. 

Since $\mathbf{1}_{\mathcal{R}}(n)$ is supported on $n$ with $\ell$ prime factors all at least $n^\eta$, if $n=p_1\cdots p_\ell\ge X^{1-\delta^2}$ and $\mathbf{1}_{\mathcal{R}}(n)=1$ then there is an $\mathbf{a}$ with $a_i\ge \eta/2$ such that $\tilde{\mathbf{1}}_{\mathcal{C}(\mathbf{a};\delta)}(p_1\cdots p_{\ell-1})=1$. Moreover, since $n\ge X^{1-\delta^2}$ we have $p_{\ell}\ge X^{1-\delta^2}/p_1\cdots p_{\ell-1}\ge X^{1-\sum_{i=1}^{\ell-1}a_i-\ell\delta}$, so in fact $\tilde{\mathbf{1}}_{\mathcal{C}^+(\mathbf{a};\delta)}(n)=1$. Since the cubes are disjoint, this happens for exactly one choice of $\mathbf{a}$. Therefore we have for any $n\in[X^{1- \delta^2},X]$
\[
\mathbf{1}_{\mathcal{R}}(n)=\sum_{\mathbf{a}}\tilde{\mathbf{1}}_{\mathcal{C}^+(\mathbf{a};\delta)}(n)\mathbf{1}_{\mathcal{R}}(n).
\]
Using this with \eqref{eq:RCubeSplit} to split the summation over hypercubes $\mathcal{C}$, we find
\begin{align*}
&\Bigl|\sum_{\substack{m\in\mathcal{A}\\ X^{1-\delta^2}<m<X}}\mathbf{1}_{\mathcal{R}}(m)-\frac{\kappa_\mathcal{A}\#\mathcal{A}}{X}\sum_{X^{1-\delta^2}<n< X}\mathbf{1}_{\mathcal{R}}(n)\Bigr|\\

&\le \sum_{\substack{\mathbf{a}\\ \mathcal{C}(\mathbf{a};2\delta)\subseteq\overline{\mathcal{R}}} }\Bigl|\sum_{\substack{m\in\mathcal{A}\\ X^{1-\delta^2}<m<X}}\tilde{\mathbf{1}}_{\mathcal{C}^+(\mathbf{a};\delta)}(m)-\frac{\kappa_\mathcal{A}\#\mathcal{A}}{X}\sum_{X^{1-\delta^2}<n< X}\tilde{\mathbf{1}}_{\mathcal{C}^+(\mathbf{a};\delta)}(n)\Bigr|\nonumber\\
&\quad+\sum_{\substack{\mathbf{a}\\ \mathcal{C}(\mathbf{a};2\delta)\cap\partial\overline{\mathcal{R}}\ne\emptyset} }O\Bigl(\sum_{\substack{m\in\mathcal{A}\\ X^{1-\delta^2}<m<X}}\tilde{\mathbf{1}}_{\mathcal{C}^+(\mathbf{a};\delta)}(m)+\sum_{X^{1-\delta^2}<n<X}\frac{\kappa_\mathcal{A}\#\mathcal{A}}{X}\tilde{\mathbf{1}}_{\mathcal{C}^+(\mathbf{a};\delta)}(n)\Bigr).

\end{align*}
