\label{eq:TrivialTerms}
\end{equation}
We now consider the contribution to \eqref{eq:CubeSplit} from $\mathcal{C}(\mathbf{a};2\delta)\cap\partial\overline{\mathcal{R}}\ne\emptyset$. Since $\mathcal{R}\subseteq[\eta,1]^\ell$, we must have $a_i\ge \eta/2$ and since the coordinates of points in $\mathcal{R}$ sum to 1 we also have $\sum_{i=1}^{\ell-1}a_i\le 1-\eta/2$. Since $\tilde{\mathbf{1}}_{\mathcal{C}^+(\mathbf{a};\delta)}(n)$ and $\Lambda_{\mathcal{C}^+(\mathbf{a};\delta)}(n)$ have the same support, which is restricted to integers with no factor less than $X^{\eta/4}$, we have $\tilde{\mathbf{1}}_{\mathcal{C}^+(\mathbf{a};\delta)}(n)\ll_\eta (\log{X})^{-\ell} \Lambda_{\mathcal{C}^+(\mathbf{a};\delta)}(n)$. Thus we have
\begin{align}
\sum_{m\in\mathcal{A}}\tilde{\mathbf{1}}_{\mathcal{C}^+(\mathbf{a};\delta)}(m)&+\frac{\kappa_\mathcal{A}\#\mathcal{A}}{X}\sum_{n<X}\tilde{\mathbf{1}}_{\mathcal{C}^+(\mathbf{a};\delta)}(n)\nonumber\\
&\ll_\eta \frac{1}{(\log{X})^\ell}\Bigl( \sum_{m\in\mathcal{A}}\Lambda_{\mathcal{C}^+(\mathbf{a};\delta)}(m)+\frac{\kappa_\mathcal{A}\#\mathcal{A}}{X}\sum_{n<X}\Lambda_{\mathcal{C}^+(\mathbf{a};\delta)}(n)\Bigr)\nonumber\\
&\le \frac{1}{(\log{X})^\ell}\Bigl|\sum_{m\in\mathcal{A}}\Lambda_{\mathcal{C}^+(\mathbf{a};\delta)}(m)-\frac{\kappa_\mathcal{A}\#\mathcal{A}}{X}\sum_{n<X}\Lambda_{\mathcal{C}^+(\mathbf{a};\delta)}(n)\Bigr|\nonumber\\
&\qquad +\frac{2}{(\log{X})^\ell}\frac{\kappa_\mathcal{A}\#\mathcal{A}}{X}\sum_{n<X}\Lambda_{\mathcal{C}^+(\mathbf{a};\delta)}(n).
\label{eq:BoundaryTerms}
\end{align}
Here we used the triangle inequality in the final line. By the prime number theorem, for any choice of $\mathbf{a}\in[0,2]^{\ell-1}$ we have
\begin{align*}
\sum_{n<X}\Lambda_{\mathcal{C}^+(\mathbf{a};\delta)}(n)&\le \sum_{\substack{p_1,\dots,p_{\ell-1}\\ p_i\in (X^{a_i},X^{a_i+\delta}]}}\Bigl(\prod_{i=1}^{\ell-1}\log{p_i}\Bigr)\sum_{p_\ell<X/p_1\cdots p_{\ell-1}}\log{p_{\ell}}\\
&\ll X\sum_{\substack{p_1,\dots,p_{\ell-1}\\ p_i\in (X^{a_i},X^{a_i+\delta}]}}\prod_{i=1}^{\ell-1}\frac{\log{p_i}}{p_i}\\
&\ll \delta^{\ell-1}X(\log{X})^{\ell-1}.
\end{align*}
Since $\mathcal{R}$ is a closed convex polytope, so is $\overline{\mathcal{R}}\subseteq\mathbb{R}^{\ell-1}$. Therefore there are $O_\mathcal{R}(\delta^{-(\ell-2)})$ hypercubes $\mathcal{C}(\mathbf{a};2\delta)$ which intersect $\partial \overline{\mathcal{R}}$. Thus the contribution to \eqref{eq:CubeSplit} from the final term of \eqref{eq:BoundaryTerms} is
\begin{align}
\ll \frac{\#\mathcal{A}}{X(\log{X})^\ell}\sum_{\substack{\mathbf{a}\\ \mathcal{C}(\mathbf{a};2\delta)\cap\partial\overline{\mathcal{R}}\ne\emptyset} }\sum_{n<X}\Lambda_{\mathcal{C}^+(\mathbf{a};\delta)}(n)
&\ll  \frac{\delta^{\ell-1}\#\mathcal{A}}{\log{X}}\sum_{\substack{\mathbf{a}\\ \mathcal{C}(\mathbf{a};2\delta)\cap\partial\overline{\mathcal{R}}\ne\emptyset} }1\nonumber\\
&\ll_\mathcal{R}  \frac{\delta\#\mathcal{A}}{\log{X}}.\label{eq:BoundaryErrorTerms}
\end{align}
We now consider the terms with $\mathcal{C}(\mathbf{a};2\delta)\subseteq\overline{\mathcal{R}}$. 
Since $\mathcal{R}\subseteq \mathcal{Q}_\ell(\eta)$, if $\mathbf{e}\in\mathcal{R}$ then $e_1\le \dots \le e_\ell$, so if $\mathbf{e}'\in\overline{\mathcal{R}}$ then $e_1'\le \dots \le e_{\ell-1}'$. Therefore, since $\mathcal{C}(\mathbf{a};2\delta)\subseteq\overline{\mathcal{R}}$, 
\begin{equation}
a_j+\delta<a_{j+1}\text{ for }j\in\{1,\dots,\ell-2\}.
\label{eq:CubeCond1}
\end{equation}
Since $\sum_{i=1}^\ell e_i=1$ and $e_{\ell-1}\le e_\ell$ for $\mathbf{e}\in\mathcal{R}$, if $\mathbf{e}'\in\overline{\mathcal{R}}$ then $e_{\ell-1}'\le 1-\sum_{i=1}^{\ell-1}e_i'$. Therefore, since $(a_1+2\delta,\dots,a_{\ell-1}+2\delta)\in\mathcal{C}(\mathbf{a};2\delta)\subseteq\overline{\mathcal{R}}$, we have 
\begin{equation}
a_{\ell-1}+2\delta\le 1-\sum_{i=1}^{\ell-1}a_i-(2\ell-2)\delta\le 1-\sum_{i=1}^{\ell-1}a_i-\ell\delta.
\label{eq:CubeCond2}
\end{equation}
Together \eqref{eq:CubeCond1} and \eqref{eq:CubeCond2} imply that at most one term occurs in the summation in $\Lambda_{\mathcal{C}^+(\mathbf{a};\delta)}$. Thus for such $\mathcal{C}(\mathbf{a};2\delta)$, since the coordinates are localized, we have
\begin{align}
\tilde{\mathbf{1}}_{\mathcal{C}^+(\mathbf{a};\delta)}(n)&=\frac{(1+O_\eta(\delta))\Lambda_{\mathcal{C}^+(\mathbf{a};\delta)}(n)}{(1-\sum_{i=1}^{\ell-1}a_i)(\prod_{i=1}^{\ell-1} a_i)(\log{X})^\ell}\nonumber\\
&=\frac{\Lambda_{\mathcal{C}^+(\mathbf{a};\delta)}(n)}{(1-\sum_{i=1}^{\ell-1}a_i)(\prod_{i=1}^{\ell-1} a_i)(\log{X})^\ell}+O_\eta(\delta \tilde{\mathbf{1}}_{\mathcal{C}^+(\mathbf{a};\delta)}(n)).
\label{eq:LambdaApprox}
\end{align}
Thus
\begin{align}
 \sum_{\substack{\mathbf{a}\\ \mathcal{C}(\mathbf{a};2\delta)\subseteq\overline{\mathcal{R}}} }&\Bigl|\sum_{m\in\mathcal{A}}\tilde{\mathbf{1}}_{\mathcal{C}^+(\mathbf{a};\delta)}(m)-\frac{\kappa_\mathcal{A}\#\mathcal{A}}{X}\sum_{n< X}\tilde{\mathbf{1}}_{\mathcal{C}^+(\mathbf{a};\delta)}(n)\Bigr|\nonumber\\
&\ll_\eta \frac{1}{(\log{X})^\ell} \sum_{\substack{\mathbf{a}\\ \mathcal{C}(\mathbf{a};2\delta)\subseteq\overline{\mathcal{R}}} }\Bigl|\sum_{m\in\mathcal{A}}\Lambda_{\mathcal{C}^+(\mathbf{a};\delta)}(m)-\frac{\kappa_\mathcal{A}\#\mathcal{A}}{X}\sum_{n< X}\Lambda_{\mathcal{C}^+(\mathbf{a};\delta)}(n)\Bigr|\nonumber\\
&\qquad +\delta\sum_{\substack{\mathbf{a}\\ \mathcal{C}(\mathbf{a};2\delta)\subseteq\overline{\mathcal{R}}} }\Bigl(\sum_{m\in\mathcal{A}}\tilde{\mathbf{1}}_{\mathcal{C}^+(\mathbf{a};\delta)}(m)+\frac{\kappa_\mathcal{A}\#\mathcal{A}}{X}\sum_{n< X}\tilde{\mathbf{1}}_{\mathcal{C}^+(\mathbf{a};\delta)}(n)\Bigr).
\label{eq:InternalTerms}
\end{align}
Since any $n=p_1\cdots p_\ell$ contributing to the second term above is counted at most once and has all prime factors at least $X^{\eta/4}$, we have
\begin{align}
\delta\sum_{\substack{\mathbf{a}\\ \mathcal{C}(\mathbf{a};2\delta)\subseteq\overline{\mathcal{R}}} }\Bigl(\sum_{m\in\mathcal{A}}\tilde{\mathbf{1}}_{\mathcal{C}^+(\mathbf{a};\delta)}(m)+\frac{\kappa_\mathcal{A}\#\mathcal{A}}{X}\sum_{n< X}\tilde{\mathbf{1}}_{\mathcal{C}^+(\mathbf{a};\delta)}(n)\Bigr)
&\ll \delta S(\mathcal{A},X^{\eta/4})+\delta\frac{\#\mathcal{A}}{X}S(\mathcal{B},X^{\eta/4})\nonumber\\
&\ll_\eta \frac{\delta \#\mathcal{A}}{\log{X}}.
\label{eq:InternalErrorTerms}
\end{align}
Here we used Lemma \ref{lmm:FundamentalLemma} and \eqref{eq:Buchstab} in the final line. Combining \eqref{eq:TrivialTerms}, \eqref{eq:BoundaryTerms}, \eqref{eq:BoundaryErrorTerms}, \eqref{eq:InternalTerms} and \eqref{eq:InternalErrorTerms}, we find \eqref{eq:CubeSplit} is bounded by
\begin{equation*}
\ll_\eta \frac{1}{(\log{X})^{\ell}}\sum_{\substack{\mathbf{a}\\ \mathcal{C}(\mathbf{a};2\delta)\cap\overline{\mathcal{R}}\ne\emptyset} }\Bigl|\sum_{m\in\mathcal{A}}\Lambda_{\mathcal{C}^+(\mathbf{a};\delta)}(m)-\kappa_\mathcal{A}\frac{\#\mathcal{A}}{X}\sum_{n< X}\Lambda_{\mathcal{C}^+(\mathbf{a};\delta)}(n)\Bigr|+\frac{\delta\#\mathcal{A}}{\log{X}}.

\end{equation*}




Thus to establish Proposition \ref{prpstn:TypeII} it is sufficient to show that for any $A>0$, we have
\begin{equation}
\sum_{\substack{m\in\mathcal{A}}}\Lambda_{\mathcal{C}^+(\mathbf{a};\delta)}(m)=\frac{\#\mathcal{A}}{X}\sum_{n<  X}\Lambda_{\mathcal{C}^+(\mathbf{a};\delta)}(n)+O_{A,\eta}\Bigl(\frac{\#\mathcal{A}}{(\log{X})^A}\Bigr),
\label{eq:CubeSum}
\end{equation}
uniformly for every hypercube $\mathcal{C}(\mathbf{a};\delta)$ of side length $\delta$ with $\mathcal{C}(\mathbf{a};2\delta)\cap\overline{\mathcal{R}}\ne\emptyset$. 

Since $\sum_{i\in\mathcal{I}}e_i\in[9/25+\epsilon,17/40-\epsilon]$ if $\mathbf{e}\in\mathcal{R}$, by taking $\mathcal{J}=\mathcal{I}$ or $\mathcal{J}=\{1,\dots,\ell\}\backslash\mathcal{I}$, we must have that $\sum_{i\in\mathcal{J}}a_j\in[9/25+\epsilon/2,17/40-\epsilon/2]\cup[23/40+\epsilon/2,16/25-\epsilon/2]$ for some $\mathcal{J}\subseteq\{1,\dots,\ell-1\}$ for any $\mathbf{a}$ such that $\mathcal{C}(\mathbf{a};2\delta)\cap\mathcal{R}\ne \emptyset$. Since $\mathcal{R}\subseteq[\eta,1]^\ell$, we have $\min_i a_i\ge \eta/2$ and $\sum_{i=1}^{\ell-1}a_i<1-\eta/2$ if $\mathcal{C}(\mathbf{a};2\delta)\cap\mathcal{R}\ne \emptyset$. Thus all hypercubes under consideration satisfy the assumptions on $\mathcal{R}_X$ of Propositions \ref{prpstn:Major}-\ref{prpstn:Exceptional}.

By Fourier expansion we have
\[
\sum_{m\in\mathcal{A}}\Lambda_{\mathcal{C}^+(\mathbf{a};\delta)}(m)=\frac{1}{X}\sum_{0\le b< X}S_{\mathcal{A}}\Bigl(\frac{b}{X}\Bigr)S_{\mathcal{C}^+(\mathbf{a};\delta)}\Bigl(\frac{-b}{X}\Bigr).
\]
We split the summation over $b$ into the sets $\mathcal{M}$, $[0,X)\backslash(\mathcal{E}\cup\mathcal{M})$ and $\mathcal{E}\backslash\mathcal{M}$, where $\mathcal{M}$ is as given by Proposition \ref{prpstn:Major}, and $\mathcal{E}$ is the set who existence is asserted by Proposition \ref{prpstn:Generic}. We then apply Propositions \ref{prpstn:Major}, \ref{prpstn:Generic} and \ref{prpstn:Exceptional} respectively to each set in turn. Let $H_{\mathcal{C}^+}(\theta)=S_{\mathcal{A}}(\theta)S_{\mathcal{C}^+(\mathbf{a};\delta)}(-\theta)$. For $C$ in the definition of $\mathcal{M}$ sufficiently large in terms of $A$ and $\eta$, this gives

\begin{align*}
\sum_{m\in\mathcal{A}}\Lambda_{\mathcal{C}^+(\mathbf{a};\delta)}(m)
&=\frac{1}{X}\sum_{b\in\mathcal{M}}H_{\mathcal{C}^+}\Bigl(\frac{b}{X}\Bigr)
+\frac{1}{X}\sum_{b\notin\mathcal{E}\cup\mathcal{M} }H_{\mathcal{C}^+}\Bigl(\frac{b}{X}\Bigr)
+\frac{1}{X}\sum_{\substack{b\in\mathcal{E}\\ b\notin \mathcal{M}}}H_{\mathcal{C}^+}\Bigl(\frac{b}{X}\Bigr)\\
&=\kappa_\mathcal{A}\frac{\#\mathcal{A}}{X}\sum_{n< X}\Lambda_{\mathcal{C}^+(\mathbf{a};\delta)}(n)+O_{A,\eta}\Bigl(\frac{\#\mathcal{A}}{(\log{X})^A}\Bigr).
\end{align*}

This gives \eqref{eq:CubeSum}, and hence completes the proof of Proposition \ref{prpstn:TypeII}.

