\Sigma'&\le \sum_{\substack{q_2\sim Q_2\\ (q_2,10)=1}}\sum_{\substack{a< d_1d_2q_1q_2\\ (a,d_1d_2q_1q_2)=1}}\sup_{|\eta|\ll 1/R}F_{R}\Bigl(\frac{a}{d_1d_2q_1q_2}+\eta\Bigr)^2&\\
&\ll d_1d_2Q_1Q_2^2\int_0^1 F_{R}(t)^2 d t+\frac{d_1d_2Q_1Q_2^2}{R}\int_0^1|F_{R}'(t)|F_{R}(t) d t.
\end{align*}

\begin{align*}
\sum_{\substack{q_2\sim Q_2\\ (q_2,10)=1}}\,\sum_{\substack{a< d q_1q_2\\ (a,d q_1q_2)=1}}\,&\sum_{\substack{|\eta|\le E/Y\\ (\eta+a/d q_1q_2)Y\in\mathbb{Z}}}F_Y\Bigl(\frac{a}{q_1q_2d}+\frac{b}{d}+\eta\Bigr)\\
&\ll E^{27/77}\Bigl(D^{27/77}(Q_1Q_2^2)^{1/21}+Q_1Q_2^2D\Bigl(\frac{Y}{D E}\Bigr)^{-10/21}\Bigr).
\end{align*}

We split $\mathcal{M}$ up as three disjoint sets
\[
\mathcal{M}=\mathcal{M}_1\cup\mathcal{M}_2\cup\mathcal{M}_3,
\]
where

\begin{align*}
\mathcal{M}_1&=\Bigl\{a\in\mathcal{M}:\Bigl|\frac{a}{X}-\frac{b}{q}\Bigr|\le\frac{(\log{X})^C}{X}\text{ for some }\,b,\,q\le (\log{X})^C,\,q\nmid X\Bigr\},\\
\mathcal{M}_2&=\Bigl\{a\in\mathcal{M}:\frac{a}{X}
=\frac{b}{q}+\nu\text{ for some }\,b,\,q\le (\log{X})^C,\,q|X,\,0<|\nu|\le \frac{(\log{X})^C}{X}\Bigr\},\\
\mathcal{M}_3&=\Bigl\{a\in\mathcal{M}:\frac{a}{X}
=\frac{b}{q}\text{ for some }\,b,\,q\le (\log{X})^C,\,q|X\Bigr\}.\\
\end{align*}

By Lemma \ref{lmm:LInfBound} and recalling $X$ is a power of 10, we have
\[
\sup_{a\in\mathcal{M}_1}\Bigl|S_{\mathcal{A}}\Bigl(\frac{a}{X}\Bigr)\Bigr|=\#\mathcal{A}\sup_{a\in\mathcal{M}_1}F_X\Bigl(\frac{a}{X}\Bigr)\ll \#\mathcal{A}\exp(-\sqrt{\log{X}}).
\]
Using the trivial bound $S_{\mathcal{R}_X}(\theta)\ll X(\log{X})^{\ell}$, where $\ell\le 2/\eta$ and noting $\#\mathcal{M}_1\ll (\log{X})^{3C}$, we obtain

\begin{equation}
\frac{1}{X}\sum_{a\in\mathcal{M}_1}S_{\mathcal{A}}\Bigl(\frac{a}{X}\Bigr)S_{\mathcal{R}_X}\Bigl(\frac{-a}{X}\Bigr)\ll_{C,\eta} \frac{\#\mathcal{A}}{(\log{X})^C}.
\label{eq:M1}
\end{equation}

This gives the result for $\mathcal{M}_1$.

We now consider $\mathcal{M}_2$. Recalling the definition of $\mathcal{R}_X$, we have that for $n<X$
\begin{equation}
\Lambda_{\mathcal{R}_X}(n)=\sum_{\substack{n=p_1\cdots p_\ell\\ p_j\in (X^{a_j},X^{a_j+\delta}]\,\text{for $j<\ell$}\\ p_\ell\ge X^{\eta/4},X^{1-\sum_ia_i-\ell\delta}}}\prod_{i=1}^\ell \log{p_i}=\sum_{\substack{n=mp\\ p\ge X^{\eta/4}\\ p\ge X^{1-\sum_ia_i-\ell\delta}}}\Lambda_{\mathcal{C}}(m)\log{p},
\label{eq:RXSum}
\end{equation}
 where $\mathcal{C}=(a_1,a_1+\delta]\times\dots\times(a_{\ell-1},a_{\ell-1}+\delta]$ is the projection of $\mathcal{R}_X$ onto the first $\ell-1$ coordinates. We note the crude bound
\begin{equation}
\sum_{m<X}\frac{\Lambda_{\mathcal{C}}(m)}{m}\le \Bigl(\sum_{p\le X}\frac{\log{p}}{p}\Bigr)^{\ell-1} \ll (\log{X})^{\ell-1}.
\label{eq:Crude}
\end{equation}
Let $\Delta=\lceil\log{X}\rceil^{-10C-10\ell}$. We note that if $a\in\mathcal{M}_2$ then $a/X=b/q+c/X$ for some integers $b,q,|c|\le (\log{X})^C$ ($c$ is an integer since $q|X$ for the set $\mathcal{M}_2$). We separate the sum $S_{\mathcal{R}_X}(a/X)$ by putting the prime variable $p$ occurring in \eqref{eq:RXSum} in short intervals of length $\Delta x/m$ and in arithmetic progressions $\Mod{q}$. We note that $\Lambda_{\mathcal{C}}$ is supported on $m\le X^{\sum_i a_i+(\ell-1)\delta}< X^{1-\eta/3}$, so we can drop the constraints $p\ge X^{\eta/4},X^{1-\sum_{i}a_i-\ell\delta}$ at the cost of some terms with $mp<X^{1-\eta/12}+X^{1-\delta}$. Thus we have

\begin{align*}
\sup_{a\in\mathcal{M}_2}S_{\mathcal{R}_X}\Bigl(\frac{a}{X}\Bigr)
&=\sup_{a\in\mathcal{M}_2}\sum_{m<X^{1-\eta/3}}\Lambda_{\mathcal{C}}(m)\sum_{p< X/m}(\log{p})e\Bigl(\frac{a m p}{X}\Bigr)\\
&\qquad +O_\ell\Bigl(\sum_{pm<X^{1-\eta/12}+X^{1-\delta}}(\log{X})^{\ell}\Bigr)\\
&=O_{C,\eta}\Bigl(\frac{X}{(\log{X})^{4C}}\Bigr)+\sup_{\substack{1\le b\le q\\ q\le (\log{X})^C \\ 0<|c|\le (\log{X})^C}}\sum_{m<X^{1-\eta/3}}\Lambda_{\mathcal{C}}(m)\sum_{r=0}^{q-1}\sum_{0\le j< \Delta^{-1}}\\ 
&\qquad\times\sum_{\substack{p\in [j\Delta X/m,(j+1)\Delta X/m) \\ p\equiv r\Mod{q}}}(\log{p})e\Bigl(mp\Bigl(\frac{b}{q}+\frac{c}{X}\Bigr)\Bigr).
\end{align*}


If $mp=j\Delta X+O(\Delta X)$ and $p\equiv r\Mod{q}$ we have
\[
e\Bigl(mp\Bigl(\frac{b}{q}+\frac{c}{X}\Bigr)\Bigr)= e\Bigl(\frac{b r m}{q}\Bigr)e(j c\Delta)+O(\Delta (\log{X})^C).
\]
By the prime number theorem in short intervals and arithmetic progressions \eqref{eq:PNT}, for $m<X^{1-\eta/3}$ and $(r,q)=1$ we have
\[
\sum_{\substack{p\in[j\Delta X/m,(j+1)\Delta X/m) \\ p\equiv r\Mod{q}}}\log{p}=\frac{\Delta X}{m\phi(q)}+O_{C,\eta}\Bigl(\frac{\Delta^2 X}{m\phi(q)}\Bigr)
\]
Thus
\begin{align*}
\sup_{a\in\mathcal{M}_2}S_{\mathcal{R}_X}\Bigl(\frac{a}{X}\Bigr)
&=\Delta X\sup_{\substack{b\le q\\ q\le (\log{X})^C \\ c\le (\log{X})^C}}\sum_{m<X^{1-\eta/3}}\frac{\Lambda_{\mathcal{C}}(m)}{m\phi(q)}
\sum_{\substack{1\le r<q\\ (r,q)=1}} e\Bigl(\frac{b r m}{q}\Bigr)\sum_{1\le j< \Delta^{-1}} e(j\Delta c)\\
&\qquad+O_{C,\eta}\Bigl(\frac{X}{(\log{X})^{4C}}\Bigr).
\end{align*}

Finally, since $c\in\mathbb{Z}$ and $c\ne 0$ and $\Delta^{-1}\in\mathbb{Z}$, we have
\[
\sum_{1\le j< \Delta^{-1}}e(j\Delta c)=-e(c)=-1=O(1).
\]
Using \eqref{eq:Crude}, this gives
\begin{align}
\sup_{a\in\mathcal{M}_2}S_{\mathcal{R}_X}\Bigl(\frac{a}{X}\Bigr)&\ll\Delta X (\log{X})^C\sum_{m<X^{1-\eta/3}}\frac{\Lambda_{\mathcal{C}}(m)}{m}+O_{C,\eta}\Bigl(\frac{X}{(\log{X})^{4C}}\Bigr)\nonumber\\
&\ll_{C,\eta} \frac{X}{(\log{X})^{4C}}.\label{eq:M2Bound}
\end{align}

Note that in the above argument for us to be able to save an arbitrary power of log it was important that we are counting elements with weight $\Lambda_{\mathcal{R}_X}(n)$ rather than $\mathbf{1}_{\mathcal{R}_X}(n)$, and that $X\nu\in\mathbb{Z}$ for $a\in\mathcal{M}_2$. 

Using the trivial bounds $S_{\mathcal{A}}(\theta)\le \#\mathcal{A}$ and $\#\mathcal{M}_2\ll (\log{X})^{3C}$ along with \eqref{eq:M2Bound}, we obtain

\begin{equation}
\frac{1}{X}\sum_{a\in\mathcal{M}_2}S_{\mathcal{A}}\Bigl(\frac{a}{X}\Bigr)S_{\mathcal{R}_X}\Bigl(\frac{-a}{X}\Bigr)\ll_{C,\eta} \frac{\#\mathcal{A}}{(\log{X})^C}.
\label{eq:M2}
\end{equation}

 Finally, we consider $\mathcal{M}_3$. By the prime number theorem in arithmetic progressions as above, we have for $(r,q)=1$ and $q\le (\log{X})^C$ that
\begin{align*}
\sum_{\substack{n< X\\ n\equiv r\Mod{q}}}\Lambda_{\mathcal{R}_X}(n)&=\frac{X}{\phi(q)}\sum_{m<X^{1-\eta/3}}\frac{\Lambda_{\mathcal{C}}(m)}{m}+O_{\eta,C}\Bigl(\frac{X}{(\log{X})^{4C}}\Bigr)\\
&=\frac{1}{\phi(q)}\sum_{n< X}\Lambda_{\mathcal{R}_X}(n)+O_{\eta,C}\Bigl(\frac{X}{(\log{X})^{4C}}\Bigr).
\end{align*}
Thus, for $(a,q)=1$
\begin{align*}
S_{\mathcal{R}_X}\Bigl(\frac{a}{q}\Bigr)&=\sum_{0\le r<q}e\Bigl(\frac{a r}{q}\Bigr)\sum_{\substack{n< X\\ n\equiv r\Mod{q}}}\Lambda_{\mathcal{R}_X}(n)\\
&=\frac{1}{\phi(q)}\Bigl(\sum_{n< X}\Lambda_{\mathcal{R}_X}(n)\Bigr)\Bigl(\sum_{\substack{0\le r<q\\ (r,q)=1}}e\Bigl(\frac{a r}{q}\Bigr)\Bigr)+O_{\eta,C}\Bigl(\frac{X}{(\log{X})^{4C}}\Bigr)\\
&=\frac{\mu(q)}{\phi(q)}\sum_{n< X}\Lambda_{\mathcal{R}_X}(n)+O_{\eta,C}\Bigl(\frac{X}{(\log{X})^{4C}}\Bigr).
\end{align*}
Since $\mu(q)=0$ for $q|10^k=X$ unless $q\in\{1,2,5,10\}$, using the trivial bounds $\#\mathcal{M}_3\ll (\log{X})^{2C}$ and $|S_\mathcal{A}(a/X)|\le \#\mathcal{A}$, we obtain

\begin{align}
\frac{1}{X}\sum_{a\in\mathcal{M}_3}&S_{\mathcal{A}}\Bigl(\frac{a}{X}\Bigr)S_{\mathcal{R}_X}\Bigl(\frac{-a}{X}\Bigr)
=\frac{1}{X}\sum_{0\le b<10}S_{\mathcal{A}}\Bigl(\frac{b}{10}\Bigr)S_{\mathcal{R}_X}\Bigl(\frac{-b}{10}\Bigr)+O_{C,\eta}\Bigl(\frac{\#\mathcal{A}}{(\log{X})^C}\Bigr)\nonumber\\
&=\frac{10}{X}\sum_{m\in\mathcal{A}}\sum_{\substack{n<X\\ n\equiv m\Mod{10}}}\Lambda_{\mathcal{R}_X}(n)+O_{C,\eta}\Bigl(\frac{\#\mathcal{A}}{(\log{X})^C}\Bigr)\nonumber\\
&=\frac{10}{\phi(10)}\Bigl(\frac{1}{X}\sum_{n< X}\Lambda_{\mathcal{R}_X}(n)\Bigr)\#\{m\in\mathcal{A}:(m,10)=1\}+O_{C,\eta}\Bigl(\frac{\#\mathcal{A}}{(\log{X})^C}\Bigr)\nonumber\\
&=\kappa_\mathcal{A}\frac{\#\mathcal{A}}{X}\sum_{n<X}\Lambda_{\mathcal{R}_X}(n)+O_{C,\eta}\Bigl(\frac{\#\mathcal{A}}{(\log{X})^C}\Bigr).
\label{eq:M3}
\end{align}

Thus \eqref{eq:M1}, \eqref{eq:M2} and \eqref{eq:M3} gives the result.

\begin{align*}
\mathcal{M}_1&=\Bigl\{a\in\mathcal{M}:\Bigl|\frac{a}{X}-\frac{b}{q}\Bigr|\le\frac{(\log{X})^C}{X}\text{ for some }\,b,\,q\le (\log{X})^C,\,q\nmid X\Bigr\},\\
\mathcal{M}_2&=\Bigl\{a\in\mathcal{M}:\frac{a}{X}
=\frac{b}{q}+\nu\text{ for some }\,b,\,q\le (\log{X})^C,\,q|X,\,0<|\nu|\le \frac{(\log{X})^C}{X}\Bigr\},\\
\mathcal{M}_3&=\Bigl\{a\in\mathcal{M}:\frac{a}{X}
=\frac{b}{q}\text{ for some }\,b,\,q\le (\log{X})^C,\,q|X\Bigr\}.\\
\end{align*}

\begin{equation}
\Lambda_{\mathcal{R}_X}(n)=\sum_{\substack{n=p_1\cdots p_\ell\\ p_j\in (X^{a_j},X^{a_j+\delta}]\,\text{for $j<\ell$}\\ p_\ell\ge X^{\eta/4},X^{1-\sum_ia_i-\ell\delta}}}\prod_{i=1}^\ell \log{p_i}=\sum_{\substack{n=mp\\ p\ge X^{\eta/4}\\ p\ge X^{1-\sum_ia_i-\ell\delta}}}\Lambda_{\mathcal{C}}(m)\log{p},
\label{eq:RXSum}
\end{equation}

\begin{align*}
\sup_{a\in\mathcal{M}_2}S_{\mathcal{R}_X}\Bigl(\frac{a}{X}\Bigr)
&=\Delta X\sup_{\substack{b\le q\\ q\le (\log{X})^C \\ c\le (\log{X})^C}}\sum_{m<X^{1-\eta/3}}\frac{\Lambda_{\mathcal{C}}(m)}{m\phi(q)}
\sum_{\substack{1\le r<q\\ (r,q)=1}} e\Bigl(\frac{b r m}{q}\Bigr)\sum_{1\le j< \Delta^{-1}} e(j\Delta c)\\
&\qquad+O_{C,\eta}\Bigl(\frac{X}{(\log{X})^{4C}}\Bigr).
\end{align*}

\begin{align*}
S_{\mathcal{R}_X}\Bigl(\frac{a}{q}\Bigr)&=\sum_{0\le r<q}e\Bigl(\frac{a r}{q}\Bigr)\sum_{\substack{n< X\\ n\equiv r\Mod{q}}}\Lambda_{\mathcal{R}_X}(n)\\
&=\frac{1}{\phi(q)}\Bigl(\sum_{n< X}\Lambda_{\mathcal{R}_X}(n)\Bigr)\Bigl(\sum_{\substack{0\le r<q\\ (r,q)=1}}e\Bigl(\frac{a r}{q}\Bigr)\Bigr)+O_{\eta,C}\Bigl(\frac{X}{(\log{X})^{4C}}\Bigr)\\
&=\frac{\mu(q)}{\phi(q)}\sum_{n< X}\Lambda_{\mathcal{R}_X}(n)+O_{\eta,C}\Bigl(\frac{X}{(\log{X})^{4C}}\Bigr).
