&\ll \sum_{\substack{j\ge 0\\ 2^j\le X^{23/80}}} 2^{(235/154-1)j} X^{59/433}\\
&\ll X^{59/433+23\times 235/(80\times 154)-23/80},
\end{align*}
and so the calculation above gives the result.

It remains to bound the sum over $a\notin\mathcal{E}$. We divide the sum into $O(\log{X})^2$ subsums where we restrict to those $a$ such that $F_X(a/X)\sim 1/B$ and $|S_{\mathcal{R}}(a/X)|\sim X/C$ for some $B\ge X^{23/80}$ and $C\le X^2$ (terms with $C>X^2$ makes a contribution $O(1/X)$). This gives

\begin{align*}
\frac{1}{X}\sum_{\substack{a<X\\ a\notin\mathcal{E}}}
&\Bigl|F_{X}\Bigl(\frac{a}{X}\Bigr)S_{\mathcal{R}}\Bigl(\frac{-a}{X}\Bigr)\Bigr|\\
&\ll \sup_{\substack{X^{23/80}\le B \\ 1\le C\le X^2}}\frac{(\log{X})^{2}}{X}\sum_{\substack{a<X\\ F_X(a/X)\sim 1/B \\ S_{\mathcal{R}}(-a/X)\sim X/C}}\Bigl|F_X\Bigl(\frac{a}{X}\Bigr)S_{\mathcal{R}}\Bigl(\frac{-a}{X}\Bigr)\Bigr|+\frac{1}{X^2}.
\end{align*}

We concentrate on the inner sum. Using Lemmas \ref{lmm:DigitDistribution} and \ref{lmm:PrimeDistribution} we see that the sum contributes

\begin{align*}
&\ll \frac{X}{B C}\#\Bigl\{a:F_X\Bigl(\frac{a}{X}\Bigr)\sim \frac{1}{B},\,\Bigl|S_{\mathcal{R}}\Bigl(\frac{-a}{X}\Bigr)\Bigr|\sim \frac{X}{C}\Bigr\}\\
&\ll \frac{X(\log{X})^{O_\eta(1)}}{B C} \min\Bigl(C^2,\,B^{235/154}X^{59/433}\Bigr)\\
&\ll_\eta X^{1+\epsilon}\frac{X^{59/866}}{B^{73/308}}.
\end{align*}

Here we used the bound $\min(x,y)\le x^{1/2}y^{1/2}$ in the last line. In particular, we see this is $O_\eta(X^{1-2\epsilon})$ if $B\ge X^{23/80}$ on verifying that $23/80\times 73/308>59/866$. Substituting this into our bound above gives the result.

\begin{align*}
\sum_{a\in\mathcal{E}} F_X\Bigl(\frac{a}{X}\Bigr)
&\ll \sum_{\substack{j\ge 0\\ 2^j\le X^{23/80}}} \#\Bigl\{0\le a<X:\,F_X\Bigl(\frac{a}{X}\Bigr)\sim 2^{-j}\Bigr\}\\
&\ll \sum_{\substack{j\ge 0\\ 2^j\le X^{23/80}}} 2^{(235/154-1)j} X^{59/433}\\
&\ll X^{59/433+23\times 235/(80\times 154)-23/80},
\end{align*}

By symmetry, we may assume that $\mathcal{I}=\{1,\dots,\ell_1\}$ for some $\ell_1< \ell$. By Dirichlet's theorem on Diophantine approximation, any $a\in[0, X)$ has a representation
\[
\frac{a}{X}=\frac{b}{q}+\nu
\]
for some integers $(b,q)=1$ with $q\le X^{1/2}$ and some real $|\nu|\le 1/X^{1/2}q$. Thus we can divide $[0,X)$ into $O(\log{X})^2$ sets $\mathcal{F}(Q,E)$ as defined by Lemma \ref{lmm:Explicit} for different parameters $Q$, $E$ satisfying $1\le Q\le X^{1/2}$ and $E=0$ or $1/X\le E\le 100 X^{1/2}/Q$. Moreover, if $a\notin\mathcal{M}$ then $a\in\mathcal{F}=\mathcal{F}(Q,E)$ for some $Q$, $E$, with $Q+E\ge (\log{X})^C$. Thus, provided $C$ is sufficiently large compared with $A$ and $\eta$, we see it is sufficient to show that
\begin{equation}
\frac{1}{X}\Bigl|\sum_{a\in\mathcal{F}\cap\mathcal{E}}S_{\mathcal{A}}\Bigl(\frac{a}{X}\Bigr)S_{\mathcal{R}_X}\Bigl(\frac{-a}{X}\Bigr)\Bigr|\ll \frac{\#\mathcal{A}}{(Q+E)^{\epsilon/20}}.
\label{eq:ExcepBound1}
\end{equation}
From the definition \eqref{eq:LambdaDef} of $\Lambda_{\mathcal{R}_X}$ and shape of $\mathcal{R}_X$ given by Proposition \ref{prpstn:Exceptional}, we have that for $n<X$
\[
\Lambda_{\mathcal{R}_X}(n)=\sum_{\substack{n_1n_2p=n\\ X^{\eta/4},X^{1-\sum_ia_i-\ell\delta}\le p}}\Lambda_{\mathcal{R}_1}(n_1)\Lambda_{\mathcal{R}_2}(n_2)\log{p},
\]
where $\mathcal{R}_1$ is the projection of $\mathcal{R}_X$ onto the first $\ell_1$ coordinates, and $\mathcal{R}_2$ is the projection onto the subsequent $\ell-\ell_1-1$ coordinates.



Since $n_1$, $n_2$, $p$ and $X$ are integers, $|\log{((X-1/2)/n_1n_2p)}|\gg 1/X$. Thus, by Perron's formula (see, for example, \cite[Chapter 17]{Davenport}), we have for $n_1,n_2,p<X$
\begin{align*}
\frac{1}{(2\pi i)^2}\int_{1/\log{X}-i X^4}^{1/\log{X}+i X^4}\Bigl(\frac{X-1/2}{n_1n_2p}\Bigr)^{s}\frac{d s}{s}
=\begin{cases}
1+O(X^{-2}),\qquad &\text{if $n_1n_2p< X$,}\\
O(X^{-2}), &\text{otherwise.}
\end{cases}
\end{align*}
We will use this to remove the constraint $n=n_1n_2p<X$ in $S_{\mathcal{R}_X}(-a/X)$. We first put $n_1,n_2,p$ into one of $O(\log{X})^3$ intervals of the form $(Y/10,Y]$, and then apply the above estimate. The $O(X^{-2})$ error term trivially makes a negligible contribution to \eqref{eq:ExcepBound1}. Thus, 
 we see that for $C$ sufficiently large, it suffices to show uniformly over all $s$ with $\Re(s)=1/\log{X}$ and all choices of $N_1,N_2,P$ with $N_1N_2P\le 1000 X$ and $P\ge X^{1-\sum_{i=1}^{\ell-1} a_i-\ell\delta}$ that

\begin{align*}
\frac{1}{X}\sum_{a\in\mathcal{F}\cap\mathcal{E}}S_{\mathcal{A}}\Bigl(\frac{a}{X}\Bigr)\sum_{\substack{n_1\sim N_1\\ n_2\sim N_2\\ p\sim P}}\frac{\Lambda_{\mathcal{R}_1}(n_1)\Lambda_{\mathcal{R}_2}(n_2)c_p}{n_1^s n_2^s p^s} e\Bigl(\frac{-an m p}{X}\Bigr)
\ll \frac{\#\mathcal{A}}{(Q+E)^{\epsilon/15}},
\end{align*}
where $c_p=\log{p}$ if $p\ge X^{\eta/4},X^{1-\sum_i a_i-\ell\delta}$ and 0 otherwise. (The integral over $s$ and the choices of $N_1,N_2,P$ contribute a factor of $O(\log{X})^4$, which is acceptable for establishing \eqref{eq:ExcepBound1} if $C$ is sufficiently large.) 

Since $\Lambda_{\mathcal{R}_1}(n_1)$ is supported on $n_1\in[X^{\sum_{i=1}^{\ell_1}a_i},X^{\sum_{i=1}^{\ell_1}a_i+\ell\delta}]$ and $\Lambda_{\mathcal{R}_2}(n_2)$ is supported on $n_2\ge X^{\sum_{\ell_1+1}^{\ell-1}a_i}$, we only need to consider $N_1N_2P\ge X^{1-\ell\delta}$ and $N_1\in [X^{\sum_{i=1}^{\ell_1}a_i},X^{\sum_{i=1}^{\ell_1}a_i+\epsilon/6}]$. But, by assumption, 
\[
\sum_{i=1}^{\ell_1}a_i\in \Bigl[\frac{9}{25}+\frac{\epsilon}{2},\frac{17}{40}-\frac{\epsilon}{2}\Bigr]\cup\Bigl[\frac{23}{40}+\frac{\epsilon}{2},\frac{16}{25}-\frac{\epsilon}{2}\Bigr],
\]
 so either $N_1$ or $N_2 P$ lie in $[X^{9/25},X^{17/40}]$. Since $\Lambda_{\mathcal{R}_1}(n_1),\Lambda_{\mathcal{R}_2}(n_2),\log{p}\ll_\ell (\log{X})^{\ell-1}$, 

\begin{align}
\frac{1}{X}\sum_{a\in\mathcal{F}\cap\mathcal{E}}S_{\mathcal{A}}\Bigl(\frac{a}{X}\Bigr)\sum_{n\sim N}\alpha_n\sum_{m\sim M}\beta_m e\Bigl(\frac{-an m}{X}\Bigr)
\ll \frac{\#\mathcal{A}}{(Q+E)^{\epsilon/12}}
\label{eq:ExcepBound2}
\end{align}

uniformly over all choices of $N\in [X^{9/25},X^{17/40}]$ and $M\le 1000 X/N$ and uniformly over all 1-bounded complex sequences $\alpha_n,\beta_m$. (Setting $\alpha_n=\Lambda_{\mathcal{R}_1}(n)/(\log{X})^{\ell}$ and $\beta_m=\sum_{p n_2=m, p\sim P, n_2\sim N_2}\Lambda_{\mathcal{R}_2}(n_2)c_p/(\log{X})^{\ell}$ gives the bound when $\sum_{i=1}^{\ell_1}a_i\in [9/25+\epsilon/2,17/40-\epsilon/2]$; the other case is analogous with $\alpha_n$ and $\beta_m$ swapped.)

Finally, let $\gamma_a$ be the 1-bounded sequence satisfying $S_{\mathcal{A}}(a/X)=\#\mathcal{A}\gamma_a F_X(a/X)$. After substituting this expression for $S_\mathcal{A}$, we see that \eqref{eq:ExcepBound2} follows immediately from  Lemma \ref{lmm:Explicit} for $C$ sufficiently large in terms of $\eta$, thus giving the result.

\begin{align*}
