\sum_{a_1,a_2\in\mathcal{E}'}F_X\Bigl(\frac{a_1}{X}\Bigr)F_X\Bigl(\frac{a_2}{X}\Bigr)\ll B^{81/77}X^{118/433}\ll B X^{23/80-\epsilon}
\]
on verifying that $4/77\times 23/80+118/433<23/80$. This gives the required bound if $N K\ll X^{57/80}/B$.

Alternatively, if $N K\gg X^{57/80}/B$, we use Lemmas \ref{lmm:Line} and \ref{lmm:LineBound} to bound $\#(\mathcal{B}_2\cap(\mathcal{E}')^2)$, and obtain

\begin{align}
\sum_{\substack{(a_1,a_2)\in\mathcal{B}_2(N,K,\delta)\\ a_1,a_2\in \mathcal{E}'}}&F_X\Bigl(\frac{a_1}{X}\Bigr)F_X\Bigl(\frac{a_2}{X}\Bigr)\le \frac{\#(\mathcal{B}_2(N,K,\delta)\cap(\mathcal{E}')^2)}{B^2}\nonumber\\
&\hspace{-1cm}\le\frac{1}{B^{2}}\#\Bigl\{a_1,a_2\in\mathcal{E}':\exists \mathbf{v}\in\mathbb{Z}^4\backslash\{\mathbf{0}\}\text{ s.t. }\|\mathbf{v}\|_2\ll \frac{X}{N^2K},\mathbf{v}\cdot\mathbf{a}=0\Bigr\}\nonumber\\
&\hspace{-1cm}\ll \frac{X^{o(1)}}{B^{2}}\Bigl((\#\mathcal{E}')^{5/4}\Bigl(\frac{X}{N^2K}\Bigr)^2+\frac{(\#\mathcal{E}')^{3/2}}{X^{1/2}}\Bigl(\frac{X}{N^2K}\Bigr)^{3}\Bigr).\label{eq:B2Bound2}
\end{align}

Here we have written $\mathbf{a}$ for the vector $(a_1,a_2,X,1)\in\mathbb{Z}^4$. 

Since $N K\gg X^{57/80}/B$, we have $X/N K\ll X^{23/80}B$. Combining this bound with \eqref{eq:BSetBound}, we obtain a bounds for $(\#\mathcal{E}')^{5/4}B^{-2}X/N K$ and $(\#\mathcal{E}')^{3/2}B^{-2}X^{-1/2}(X/N K)^2$ of the form $X^a B^b$ for some $b>0$. Since we are only considering $B\ll X^{23/80}$, these expressions are maximized when $B\asymp X^{23/80}$. When $B\asymp X^{23/80}$ we have $\#\mathcal{E}'\ll X^{23/40}$ and $X/N K\ll X^{23/40}$. Thus we obtain the bounds

\begin{align*}
\frac{(\#\mathcal{E}')^{5/4}}{B^2}\frac{X}{N K}&\ll X^{115/160}=X^{23/32},\\

\frac{(\#\mathcal{E}')^{3/2}}{B^2 X^{1/2}}\Bigl(\frac{X}{N K}\Bigr)^2& \ll X^{75/80}=X^{15/16}.
\end{align*}

Substituting these bounds into \eqref{eq:B2Bound2} gives

\begin{align*}
\sum_{\substack{ (a_1,a_2)\in\mathcal{B}_2(N,K,\delta) \\ a_1,a_2\in\mathcal{E}' }}F_X\Bigl(\frac{a_1}{X}\Bigr)F_X\Bigl(\frac{a_2}{X}\Bigr)\ll \Bigl(\frac{X^{23/32}}{N^2}+\frac{X^{15/16}}{N^{3}}\Bigr)\frac{X^{1+o(1)}}{N K}.
\end{align*}

We can then verify that $2\times 9/25>23/32$ and that $3\times 9/25>15/16$, so for $N\gg X^{9/25}$ this is $O(X^{1-\epsilon}/NK)$, as required.
